//! Executed-original F938/F929 whole-second and cargo comparison.
use ffe_rs::flight::Flight;

#[test]
#[ignore = "Local-only: FFE_RECHARGE_VECTORS generated by the original executable"]
fn executed_original_recharge_and_reserve() {
    let bytes = std::fs::read_to_string(std::env::var_os("FFE_RECHARGE_VECTORS").unwrap()).unwrap();
    let mut count = 0;
    for line in bytes.lines() {
        let v: serde_json::Value = serde_json::from_str(line).unwrap();
        let word = |key: &str| v[key].as_u64().unwrap() as u32;
        let mut state = Flight::default();
        state.combat.energy = word("energy_in");
        state.combat.drive = word("drive") as u8;
        state.loadout.general = word("general");
        state.shields = [word("shield_in") as u16, word("shield_max") as u16];
        let full = (word("mass") as u16).wrapping_mul(4);
        state.hull = [23, full];
        state.hold = vec![0; ffe_core::market::NAMES];
        state.hold[ffe_core::hyperspace::HYDROGEN] = word("fuel_in") as u16;
        state.hold[ffe_core::hyperspace::MILITARY_FUEL] = word("fuel_in") as u16;
        let sum = v["thrust"]
            .as_array()
            .unwrap()
            .iter()
            .map(|w| (w.as_i64().unwrap() as i32).abs())
            .sum();
        state.recharge(word("seconds"), full);
        state.spend_thrust_energy(word("seconds"), word("mass") as u16, sum);
        assert_eq!(state.combat.energy, word("energy"), "energy case {count}");
        assert_eq!(
            u32::from(state.shields[0]),
            word("shield"),
            "shield case {count}"
        );
        assert_eq!(u32::from(state.hull[0]), word("hull"), "hull case {count}");
        for (key, slot) in [
            ("hydrogen", ffe_core::hyperspace::HYDROGEN),
            ("military", ffe_core::hyperspace::MILITARY_FUEL),
            ("waste", ffe_core::hyperspace::RADIOACTIVES),
        ] {
            assert_eq!(u32::from(state.hold[slot]), word(key), "{key} case {count}");
        }
        count += 1;
    }
    assert_eq!(count, 192);
}
